  "glossary": [
    {
      "term": "AUT",
      "definition": "Application under test. The web app, mobile app or desktop app a case exercises. Cases are grouped by AUT and each AUT owns a Knowledge Base.",
      "page": "test-cases"
    },
    {
      "term": "Case",
      "definition": "One YAML file in the tests repo describing a scenario as ordered steps. It is the unit that runs, passes or fails.",
      "page": "test-cases"
    },
    {
      "term": "Step",
      "definition": "One line of intent inside a case, such as an action, an assertion or a query. The engine executes steps in order and records evidence for each.",
      "page": "test-cases"
    },
    {
      "term": "Assertion",
      "definition": "A step that judges the screen instead of changing it. Assertions never read the Knowledge Base, so they cannot be talked into passing.",
      "page": "test-cases"
    },
    {
      "term": "Run",
      "definition": "A named bundle of cases executed together under one profile. A run produces one report.",
      "page": "run-manager"
    },
    {
      "term": "Report",
      "definition": "The stored result of a run: per-case status, step evidence, screenshots, tokens, cost and the AI verdict.",
      "page": "reports"
    },
    {
      "term": "Verdict",
      "definition": "The model's reading of a failure, sorted into a bucket: potential product defect, test case or data, environment or flaky. It guides triage; a person still decides.",
      "page": "reports"
    },
    {
      "term": "Finding",
      "definition": "A failure the verdict considers worth a bug, held in the bug pool until someone approves, dismisses or files it.",
      "page": "reports"
    },
    {
      "term": "Profile",
      "definition": "A reviewed YAML under _profiles/ that fixes device, deep-testing options, knowledge base, model and allowed tools for every run that binds it.",
      "page": "profiles"
    },
    {
      "term": "Device",
      "definition": "A concrete target the engine can drive: a managed browser, a phone over adb, a simulator, or the desktop screen.",
      "page": "devices"
    },
    {
      "term": "Skill",
      "definition": "A parameterised flow under _hooks/ that a case calls with one line, for example a login. Skills hold their own vault references.",
      "page": "skills"
    },
    {
      "term": "Tool",
      "definition": "A declared HTTP request or page script under _tools/ that a step may call when the bound profile allows the host.",
      "page": "tools"
    },
    {
      "term": "MCP server",
      "definition": "An external tool server declared under _mcp/. Its tools are callable only after a person approves them and the profile names the server.",
      "page": "mcp-servers"
    },
    {
      "term": "Knowledge Base",
      "definition": "A KB.md per AUT with principles, interaction tips and known blockers. Injected into act and heal steps, never into assertions.",
      "page": "knowledge-base"
    },
    {
      "term": "Vault",
      "definition": "Server-side store for variables and secrets. Steps reference them as <<KEY>>; secret values never appear in the UI, logs or reports.",
      "page": "context-variables"
    },
    {
      "term": "Dry run",
      "definition": "A walk of a draft case that executes it step by step to prove it before it is accepted into the suite.",
      "page": "workflow-author-case"
    },
    {
      "term": "Proposal",
      "definition": "A generated case parked under _proposals/. It cannot run or be listed until a person accepts it to a path in the suite.",
      "page": "proposals"
    },
    {
      "term": "Self-heal",
      "definition": "When a step fails on a locator or timing problem, the engine retries with a fresh read of the screen and records what it learned as a known blocker.",
      "page": "workflow-triage"
    },
    {
      "term": "Re-judge",
      "definition": "Ask the model to re-evaluate the verdict of a stored report with the same evidence, for example after the Knowledge Base changed.",
      "page": "reports"
    },
    {
      "term": "Coverage",
      "definition": "A per-project map from product areas and claims to the cases that prove them, scored by the latest runs.",
      "page": "coverage"
    },
    {
      "term": "Keval",
      "definition": "The in-app agent. It authors cases, starts runs, walks drafts and triages results through chat, using the same tools you see in the UI.",
      "page": "keval-agent"
    },
    {
      "term": "Intent",
      "definition": "One user goal a test can prove, in the product's words with the outcome that proves it. Keval breaks a requirement into intents and authors, generates or explores each.",
      "page": "requirement-to-cases"
    },
    {
      "term": "Walk",
      "definition": "Keval performs a stored case step by step, rewrites the actions the app refuses, keeps every assertion, and proposes the fixed clone.",
      "page": "walk-explore"
    },
    {
      "term": "Explore",
      "definition": "A run that looks deeper after every step through the UI, API, console and assertion lenses and reports bugs and improvements. It never edits the case or counts in the pass rate.",
      "page": "walk-explore"
    },
    {
      "term": "Plugin",
      "definition": "A signed package that contributes prompt sections, playbooks or Docs pages to the engine and updates from a feed without a new app build.",
      "page": "keval-plugins"
    },
    {
      "term": "Budget",
      "definition": "Limits on tokens, cost and workers per case and per working session. A run that hits a limit stops instead of spending on.",
      "page": "monitoring"
    }
  ]
}

